export type OperationId = keyof typeof API_OPERATIONS;
type SuccessStatus = 200 | 201 | 202 | 203 | 204 | 205 | 206;
type ResponseBody<T> = T extends { content: { "application/json": infer Body } } ? Body : T extends { content?: never } ? void : unknown;
export type OperationResponse<Id extends OperationId> = ResponseBody<operations[Id]["responses"][keyof operations[Id]["responses"] & SuccessStatus]>;
export type OperationRequestBody<Id extends OperationId> = operations[Id] extends { requestBody: { content: { "application/json": infer Body } } } ? Body : never;
export type OperationQuery<Id extends OperationId> = operations[Id] extends { parameters: { query?: infer Query } } ? Query : never;

