export function operationPath<Id extends OperationId>(id: Id, ...args: keyof OperationPathParameters[Id] extends never ? [] : [OperationPathParameters[Id]]): string {
  const params = (args[0] ?? {}) as Record<string, string | number>;
  return API_OPERATIONS[id].path.replace(/\{([^{}]+)\}/g, (_match, key: string) => {
    const value = params[key];
    if (value == null) throw new Error(`Missing path parameter ${key} for ${id}`);
    return encodeURIComponent(String(value));
  });
}

function operationPattern(template: string): RegExp {
  const escaped = template.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp(`^${escaped.replace(/\\\{[^{}]+\\\}/g, "[^/]+")}$`);
}

export function assertOperationRequest(path: string, method: string): void {
  const pathname = path.split("?", 1)[0] ?? path;
  const normalizedMethod = method.toUpperCase();
  for (const operation of Object.values(API_OPERATIONS)) {
    if (operation.method === normalizedMethod && operationPattern(operation.path).test(pathname)) return;
  }
  throw new Error(`Unknown API operation ${normalizedMethod} ${pathname}`);
}
